<?php require __DIR__.'/includes/auth.php';require __DIR__.'/config/database.php';$pdo=db();if($_SERVER['REQUEST_METHOD']==='POST'&&trim($_POST['titulo']??'')!==''){$pdo->prepare('INSERT INTO ideias(titulo,descricao,status) VALUES(?,?,?)')->execute([trim($_POST['titulo']),trim($_POST['descricao']),trim($_POST['status'])]);header('Location: ideias.php');exit;}$pageTitle='Ideias';$rows=$pdo->query('SELECT * FROM ideias ORDER BY id DESC')->fetchAll();require __DIR__.'/includes/header.php';?>
<div class="row g-4"><div class="col-lg-4"><div class="panel-card"><h2 class="h5">Nova ideia</h2><form method="post"><div class="mb-3"><label class="form-label">Título</label><input class="form-control" name="titulo" required></div><div class="mb-3"><label class="form-label">Descrição</label><textarea class="form-control" name="descricao" rows="5"></textarea></div><div class="mb-3"><label class="form-label">Status</label><select class="form-select" name="status"><option>Nova</option><option>Em análise</option><option>Aprovada</option><option>Descartada</option></select></div><button class="btn btn-dark w-100">Salvar ideia</button></form></div></div><div class="col-lg-8"><div class="panel-card"><h2 class="h5 mb-3">Banco de ideias</h2><?php foreach($rows as $r): ?><div class="border rounded-3 p-3 mb-2"><div class="d-flex justify-content-between"><strong><?= htmlspecialchars($r['titulo']) ?></strong><span class="badge text-bg-light border"><?= htmlspecialchars($r['status']) ?></span></div><div class="text-secondary mt-1"><?= nl2br(htmlspecialchars($r['descricao'])) ?></div></div><?php endforeach; ?><?php if(!$rows): ?><div class="empty-state">Nenhuma ideia cadastrada.</div><?php endif; ?></div></div></div>
